const c = $('Config - Regionen + Schwelle').first().json;
const regions = c.regions || ['Ingolstadt', 'Kelheim', 'Regensburg', 'München'];
const now = new Date();
const todayIso = now.toISOString().slice(0, 10);
const yNow = now.getUTCFullYear();
const mNow = now.getUTCMonth() + 1;
// Ab Oktober keine regulären Feste mehr für das laufende Jahr suchen
const y1 = mNow >= 10 ? yNow + 1 : yNow;
const y2 = y1 + 1;
const y3 = y1 + 2;
const runId = (c.useMockTavily === true ? 'mock-' : '') + String(c.runId || '');
const defaultRange = c.tavilyTimeRange || 'month';
const base = {
  runId,
  todayIso,
  minScore: c.minScore ?? 60,
  maxCandidates: c.maxCandidates ?? 18,
  maxVerify: c.maxVerify ?? 6,
  perRegionCap: c.perRegionCap ?? 5,
  maxSourceAgeDays: c.maxSourceAgeDays ?? 180,
  nimModel: c.nimModel || 'nvidia/nemotron-3.5-bolt-e4b',
  nimFallback: c.nimFallback || 'poolside/laguna-xs-2.1',
  prefilter: c.prefilter !== false,
  useMockTavily: c.useMockTavily === true,
};
const templates = [
  { fn: (r) => `Festwirt gesucht ${r} ${y1} OR ${y2}`, timeRange: defaultRange },
  { fn: (r) => `Festzelt Bewirtung Ausschreibung Bewerbung ${r} ${y1} OR ${y2}`, timeRange: defaultRange },
  { fn: (r) => `Volksfest OR Dult Festwirt Vergabe ${r} ${y1} OR ${y2}`, timeRange: defaultRange },
  { fn: (r) => `Schützenfest OR Feuerwehrfest Gründungsfest Festwirt ${r} ${y1} OR ${y2}`, timeRange: defaultRange },
  { fn: (r) => `Kirchweih OR Kirta Festzelt Verpachtung ${r} ${y1}`, timeRange: defaultRange },
  { fn: (r) => `Festwirt abgesprungen Ersatz kurzfristig ${r}`, timeRange: 'week' },
  { fn: (r) => `Festausschuss gegründet Gründungsfest ${y2} OR ${y3} ${r}`, timeRange: 'month' },
];
const items = [];
for (const region of regions) {
  for (const tpl of templates) {
    items.push({ json: Object.assign({}, base, { query: tpl.fn(region), region, timeRange: tpl.timeRange }) });
  }
}
return items;

const q = $json.query || '';
const todayIso = $json.todayIso || new Date().toISOString().slice(0, 10);
function plusDays(days) { const d = new Date(); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().slice(0, 10); }
function plusMonths(m) { const d = new Date(); d.setUTCMonth(d.getUTCMonth() + m); return d.toISOString().slice(0, 10); }
function de(iso) { const p = iso.split('-'); return p[2] + '.' + p[1] + '.' + p[0]; }
const d1 = plusMonths(14), d1End = plusMonths(14), dl1 = plusDays(35);
const d2 = plusMonths(16), dl2 = plusDays(-10); // abgelaufene Frist -> muss hart gefiltert werden!
const d3 = plusMonths(12);
const results = [
  {
    title: '150 Jahre Schützenverein Kelheim – Festwirt gesucht',
    url: 'https://sv-kelheim-beispiel.de/jubilaeum-150',
    published_date: plusDays(-5),
    content: 'Der Schützenverein Kelheim feiert 150 Jahre mit großem Festzelt. Bewerbungsfrist bis ' + de(dl1) + '.',
    raw_content: 'Veröffentlicht am ' + de(plusDays(-5)) + '. 150 Jahre Schützenverein Kelheim e.V. vom ' + de(d1) + ' bis ' + de(d1End) + ' auf dem Festplatz Kelheim (1200 Gäste). Für die Festzelt-Bewirtung wird ein Festwirt gesucht. Bewerbungen bis ' + de(dl1) + ' an Festausschuss Hans Muster, 09441 123456, fest@sv-kelheim-beispiel.de.',
    score: 0.93,
  },
  {
    title: 'Volksfest Musterstadt – Bewerbung abgelaufen (Testfall)',
    url: 'https://volksfest-abgelaufen-beispiel.de/ausschreibung',
    published_date: plusDays(-45),
    content: 'Ausschreibung Festwirt Volksfest Musterstadt am ' + de(d2) + '. Einsendeschluss war der ' + de(dl2) + '.',
    raw_content: 'Veröffentlicht am ' + de(plusDays(-45)) + '. Die Gemeinde Musterstadt im Landkreis Ingolstadt sucht einen Festwirt für das Volksfest am ' + de(d2) + '. Bewerbungsfrist endete am ' + de(dl2) + '. Kontakt: rathaus@musterstadt-beispiel.de.',
    score: 0.90,
  },
  {
    title: 'Feuerwehrfest Regensburg-Land – Festausschuss gegründet',
    url: 'https://ff-musterdorf-regensburg-beispiel.de/festausschuss',
    published_date: plusDays(-8),
    content: '125-jähriges Gründungsfest am ' + de(d3) + ', Festausschuss hat Arbeit aufgenommen.',
    raw_content: 'Artikel vom ' + de(plusDays(-8)) + '. Die Freiwillige Feuerwehr Musterdorf im Landkreis Regensburg (gegründet ' + (Number(d3.slice(0, 4)) - 125) + ') plant ihr 125-jähriges Gründungsfest am ' + de(d3) + ' mit Festzelt. Der Festausschuss wurde konstituiert, Festwirt und Brauerei sind noch nicht vergeben. 1. Vorstand Franz Beispiel, info@ff-musterdorf-regensburg-beispiel.de.',
    score: 0.87,
  },
];
return [{ json: { query: q, todayIso, results, response_time: 0, _mock: true } }];

const queries = $('Queries generieren').all();
const byQuery = new Map();
for (const q of queries) { if (q.json && q.json.query) byQuery.set(q.json.query, q.json); }
const items = [];
let lineageErrors = 0;
for (const item of $input.all()) {
  let src = null;
  const echoQuery = item.json.query;
  if (echoQuery && byQuery.has(echoQuery)) src = byQuery.get(echoQuery);
  else {
    const pi = item.pairedItem;
    const idx = Array.isArray(pi) ? (pi[0] && pi[0].item) : (pi && pi.item);
    src = typeof idx === 'number' ? (queries[idx] && queries[idx].json) : null;
  }
  if (!src || !src.query) { lineageErrors++; continue; }
  const results = item.json.results || [];
  for (const hit of results.slice(0, 6)) {
    if (!hit.url) continue;
    // PDFs nicht mehr pauschal blocken (Gemeinde-Ausschreibungen sind oft PDFs), nur Medien-Dateien raus
    if (/\.(jpg|jpeg|png|gif|bmp|webp|mp4|mp3|zip)(\?.*)?$/i.test(hit.url)) continue;
    const raw = (hit.raw_content || hit.content || '').replace(/\s+/g, ' ').trim();
    const pubRaw = hit.published_date || hit.publishedDate || null;
    const publishedDate = pubRaw ? String(pubRaw).slice(0, 10) : null;
    items.push({
      json: {
        url: hit.url,
        title: hit.title || '',
        snippet: raw.slice(0, 700),
        text: raw,
        publishedDate,
        tavilyScore: hit.score ?? null,
        query: src.query,
        region: src.region,
        runId: src.runId,
        todayIso: src.todayIso,
        minScore: src.minScore,
        maxCandidates: src.maxCandidates,
        maxVerify: src.maxVerify,
        perRegionCap: src.perRegionCap,
        maxSourceAgeDays: src.maxSourceAgeDays,
        nimModel: src.nimModel,
        nimFallback: src.nimFallback,
        prefilter: src.prefilter,
        useMockTavily: src.useMockTavily === true,
      },
    });
  }
}
if (items.length === 0 && lineageErrors > 0) throw new Error('Lineage verloren: ' + lineageErrors + ' Suchantworten nicht zuordenbar.');
if (items.length === 0) return [{ json: { _empty: true, reason: 'no_search_results' } }];
return items;

const inputs = $input.all().filter(i => i.json && !i.json._empty);
const cfg = $('Config - Regionen + Schwelle').first().json || {};
if (!inputs.length) return [{ json: { _empty: true, skippedKnown: 0, skippedOld: 0, skippedPrefilter: 0, skippedShort: 0, skippedDup: 0, skippedQuota: 0 } }];

// Bekannte & gelöschte URLs vorab aus dem Backend laden (Fallback: leer)
let knownUrls = new Set();
try {
  const knownRes = ($('Bekannte URLs laden (Fest)').first() || {}).json || {};
  if (Array.isArray(knownRes.urls)) knownUrls = new Set(knownRes.urls.map(u => String(u).toLowerCase()));
} catch (e) {}

const first = inputs[0].json;
const maxCandidates = Number(first.maxCandidates || cfg.maxCandidates || 18);
const perRegionCap = Number(first.perRegionCap || cfg.perRegionCap || 5);
const maxSourceAgeDays = Number(first.maxSourceAgeDays || cfg.maxSourceAgeDays || 180);
const prefilter = first.prefilter !== false;
const nowMs = Date.now();
const maxAgeMs = maxSourceAgeDays * 864e5;

const KEYWORDS = /festwirt|zeltverleih|ausschreibung|bewerbung|jubil|schuetzen|schützen|volksfest|dult|kirchweih|kirta|trachten|feuerwehrfest|musikfest|gastronom|bewirtung|verpachtung|gründungsfest|festausschuss|abgesprungen/i;
const NEGATIVE = /impressum|datenschutz|stellenanzeige|shop|ticketverkauf|login|warenkorb/i;
const norm = (u) => String(u || '').trim().toLowerCase().replace(/[?#].*$/, '').replace(/\/+$/, '');

const seen = new Set();
const uniq = [];
let skippedPrefilter = 0, skippedShort = 0, skippedDup = 0, skippedKnown = 0, skippedOld = 0;

for (const item of inputs) {
  const j = item.json;
  const key = norm(j.url);
  if (!key) continue;
  if (knownUrls.has(key)) { skippedKnown++; continue; }
  if (seen.has(key)) { skippedDup++; continue; }
  const text = String(j.text || j.snippet || '');
  if (text.length < 120) { skippedShort++; continue; }
  if (j.publishedDate && /^\d{4}-\d{2}-\d{2}$/.test(j.publishedDate)) {
    const pd = new Date(j.publishedDate + 'T00:00:00Z');
    if (!isNaN(pd.getTime()) && (nowMs - pd.getTime()) > maxAgeMs) { skippedOld++; continue; }
  }
  if (prefilter) {
    const probe = (j.title || '') + ' ' + (j.snippet || '');
    if (!KEYWORDS.test(probe)) { skippedPrefilter++; continue; }
    if (NEGATIVE.test(probe) && !KEYWORDS.test(j.title || '')) { skippedPrefilter++; continue; }
  }
  seen.add(key);
  uniq.push(Object.assign({}, j, { sourceUrlNormalized: key }));
}

// Neueste Quellen mit hohem Tavily-Score priorisieren
uniq.sort((a, b) => {
  const aFresh = a.publishedDate ? 0.15 : 0;
  const bFresh = b.publishedDate ? 0.15 : 0;
  return ((b.tavilyScore || 0) + bFresh) - ((a.tavilyScore || 0) + aFresh);
});

const perRegion = {};
const picked = [];
for (const j of uniq) {
  const r = j.region || '?';
  perRegion[r] = (perRegion[r] || 0) + 1;
  if (perRegion[r] <= perRegionCap) picked.push(j);
  if (picked.length >= maxCandidates) break;
}
const skippedQuota = uniq.length - picked.length;
if (!picked.length) {
  return [{ json: { _empty: true, skippedKnown, skippedOld, skippedPrefilter, skippedShort, skippedDup, skippedQuota } }];
}
return picked.map(j => ({
  json: {
    url: j.url,
    sourceUrlNormalized: j.sourceUrlNormalized,
    title: j.title,
    snippet: String(j.snippet || '').slice(0, 700),
    text: String(j.text || '').slice(0, 4000),
    publishedDate: j.publishedDate || null,
    region: j.region,
    runId: j.runId,
    todayIso: j.todayIso,
    minScore: j.minScore,
    maxVerify: j.maxVerify,
    maxSourceAgeDays: j.maxSourceAgeDays,
    nimModel: j.nimModel,
    nimFallback: j.nimFallback,
    tavilyScore: j.tavilyScore,
    useMockTavily: j.useMockTavily === true,
    skippedKnown,
    skippedOld,
    skippedPrefilter,
    skippedShort,
    skippedDup,
    skippedQuota,
  },
}));

function extractJson(text) {
  if (!text || typeof text !== 'string') return null;
  const t = text.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(t); } catch (e) {}
  const s = t.indexOf('{'), e2 = t.lastIndexOf('}');
  if (s !== -1 && e2 > s) { try { return JSON.parse(t.slice(s, e2 + 1)); } catch (e) {} }
  return null;
}
function parseIso(raw) {
  if (!raw) return null;
  let ds = String(raw).trim();
  const de = ds.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (de) ds = de[3] + '-' + de[2].padStart(2, '0') + '-' + de[1].padStart(2, '0');
  if (!/^\d{4}-\d{2}-\d{2}/.test(ds)) return null;
  const dt = new Date(ds.slice(0, 10) + 'T00:00:00Z');
  return isNaN(dt.getTime()) ? null : { iso: ds.slice(0, 10), dt };
}
const hostOf = (u) => {
  const m = String(u || '').toLowerCase().match(/^https?:\/\/([^\/?#:]+)/);
  return m ? m[1].split('@').pop().replace(/^www\./, '') : '';
};

const TYPES = ['volksfest','schuetzen','trachten','feuerwehr','musik','kirchweih'];
const JUBILEES = [50,60,70,75,80,90,100,110,120,125,130,140,150,160,175,200];
const FS = ['open','taken','unknown','closed'];
const RF = ['core','adjacent','far'];
const ET = ['volksfest','schuetzen','trachten','feuerwehr','musik','kirchweih','other'];
const PS = ['none','festausschuss','termin','presse'];

const today = new Date();
const todayIso = today.toISOString().slice(0, 10);
const todayStartUtc = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
const sources = $('Kandidaten vorbereiten').all().filter(i => i.json && !i.json._empty);
const inputs = $input.all();

let knownEventKeys = new Set();
try {
  const knownRes = ($('Bekannte URLs laden (Fest)').first() || {}).json || {};
  if (Array.isArray(knownRes.eventKeys)) knownEventKeys = new Set(knownRes.eventKeys.map(k => String(k).toLowerCase()));
} catch (e) {}

const out = [];
let httpErrors=0, route404=0, model404=0, authErr=0, firstError='';
let truncated=0, reasoningOnly=0, noJson=0, notEvent=0, lowScore=0, takenSkip=0, closedSkip=0, farSkip=0, lineageErrors=0;
let pastEventSkip=0, expiredDeadlineSkip=0, oldSourceSkip=0, noDateSkip=0, knownEventSkip=0;
let maxVerify = 6;

for (const item of inputs) {
  const pi = item.pairedItem;
  const idx = Array.isArray(pi) ? (pi[0] && pi[0].item) : (pi && pi.item);
  const src = typeof idx === 'number' ? (sources[idx] && sources[idx].json) : null;
  if (!src || !src.url) { lineageErrors++; continue; }
  maxVerify = Number(src.maxVerify || 6);
  if (item.json.error) {
    const em = String(item.json.error.message || '');
    if (/page not found/i.test(em)) route404++;
    else if (/not found for account/i.test(em)) model404++;
    else if (/401|403|unauthorized/i.test(em)) authErr++;
    httpErrors++;
    if (!firstError) firstError = em.slice(0, 200);
    continue;
  }
  const choice = (item.json.choices && item.json.choices[0]) || {};
  const msg = choice.message || {};
  let content = msg.content;
  if (Array.isArray(content)) content = content.map(c => (c && c.text) || '').join('');
  if (!content) {
    if (choice.finish_reason === 'length') truncated++;
    else if (msg.reasoning_content) reasoningOnly++;
    else noJson++;
    continue;
  }
  const d = extractJson(content);
  if (!d) { noJson++; continue; }
  if (d.isEventPage === false) { notEvent++; continue; }

  let fs = String(d.festwirtStatus || 'unknown').toLowerCase();
  if (FS.indexOf(fs) === -1) fs = 'unknown';
  const emergency = d.emergency === true;
  if (emergency && (fs === 'taken' || fs === 'unknown')) fs = 'open';
  if (fs === 'taken') { takenSkip++; continue; }
  if (fs === 'closed') { closedSkip++; continue; }

  let rf = String(d.regionFit || 'far').toLowerCase();
  if (RF.indexOf(rf) === -1) rf = 'far';
  if (rf === 'far') { farSkip++; continue; }

  // HARTER FRIST-CHECK gegen heute
  const dlParsed = parseIso(d.applicationDeadline);
  const applicationDeadline = dlParsed ? dlParsed.iso : null;
  if (dlParsed && dlParsed.dt.getTime() < todayStartUtc) {
    expiredDeadlineSkip++;
    continue;
  }

  // HARTER QUELLEN-ALTER-CHECK gegen heute
  const srcParsed = parseIso(d.sourceDate) || parseIso(src.publishedDate);
  const sourceDate = srcParsed ? srcParsed.iso : null;
  const maxAgeDays = Number(src.maxSourceAgeDays || 180);
  if (srcParsed && (today.getTime() - srcParsed.dt.getTime()) > maxAgeDays * 864e5) {
    oldSourceSkip++;
    continue;
  }

  // HARTER EVENT-DATUM-CHECK gegen heute
  const evParsed = parseIso(d.eventDate);
  let eventDate = evParsed ? evParsed.iso : null;
  let months = null, dateAssumed = false;
  const eyRaw = Number(d.eventYear);
  const eventYear = (Number.isInteger(eyRaw) && eyRaw >= 2000 && eyRaw <= today.getUTCFullYear() + 5)
    ? eyRaw
    : (evParsed ? evParsed.dt.getUTCFullYear() : null);

  if (evParsed) {
    if (evParsed.dt.getTime() < todayStartUtc - 14 * 864e5) { pastEventSkip++; continue; }
    months = (evParsed.dt.getTime() - today.getTime()) / (864e5 * 30.44);
  } else if (eventYear) {
    if (eventYear < today.getUTCFullYear()) { pastEventSkip++; continue; }
    months = (Date.UTC(eventYear, 5, 1) - today.getTime()) / (864e5 * 30.44);
    dateAssumed = true;
    if (months < 0) { pastEventSkip++; continue; }
  } else if (!applicationDeadline && !emergency) {
    // Kein Eventdatum, kein Jahr, keine Frist -> Evergreen/Archivseite verwerfen
    noDateSkip++;
    continue;
  }

  let et = String(d.eventType || 'other').toLowerCase();
  if (ET.indexOf(et) === -1) et = 'other';
  let ps = String(d.planningSignal || 'none').toLowerCase();
  if (PS.indexOf(ps) === -1) ps = 'none';
  const recurring = d.recurring === true;
  const fy = Number(d.foundingYear);
  const foundingYear = (Number.isInteger(fy) && fy >= 1800 && fy <= today.getUTCFullYear()) ? fy : null;
  const jy = Number(d.jubileeYears);

  let score = 0; const reasons = [];
  if (JUBILEES.indexOf(jy) !== -1) { score += 40; reasons.push(jy + ' Jahre Jubilaeum'); }
  if (fs === 'open') { score += 35; reasons.push('Festwirt gesucht'); }
  else { score += 15; reasons.push('Festwirt unklar'); }
  if (rf === 'core') { score += 20; reasons.push('Kernregion'); }
  else if (rf === 'adjacent') { score += 10; reasons.push('Nachbarregion'); }
  if (applicationDeadline) { score += 10; reasons.push('Frist ' + applicationDeadline); }

  const leadType = fs === 'open' ? 'open' : 'signal';
  if (months !== null) {
    if (leadType === 'signal' && months >= 12 && months <= 42) { score += 15; reasons.push('Connect-Fenster ' + Math.round(months) + ' Monate'); }
    else {
      if (months >= 6 && months <= 24) { score += 15; reasons.push('in ' + Math.round(months) + ' Monaten'); }
      else if (months < 6 && !emergency) { score -= 15; reasons.push('kurzfristig'); }
      else if (months > 42) { score -= 15; reasons.push('weit entfernt'); }
    }
  }
  if (TYPES.indexOf(et) !== -1) score += 10;
  if (ps !== 'none') { score += 15; reasons.push('Signal: ' + ps); }
  if (emergency) { score += 30; reasons.push('NOTFALL'); }
  if (d.incumbentFestwirt || d.brauereiPartner) reasons.push('Incumbent: ' + (d.incumbentFestwirt || d.brauereiPartner));
  score = Math.max(0, Math.min(100, score));

  const minScore = Number(src.minScore ?? 60);
  if (!emergency && score < minScore) { lowScore++; continue; }

  const domain = hostOf(src.url);
  const org = String(d.organizer || domain).toLowerCase().replace(/\s+/g, ' ').trim();
  const eventKey = org + '|' + (eventDate || eventYear || '') + '|' + (Number.isFinite(jy) ? jy : '');
  if (knownEventKeys.has(eventKey.toLowerCase())) { knownEventSkip++; continue; }

  const qSubject = String(d.organizer || d.title || domain).replace(/["']/g, '').trim().slice(0, 70);
  const qLoc = String(d.location || src.region || '').replace(/["']/g, '').trim();
  const verifyQuery = '"' + qSubject + '" ' + qLoc + ' Festwirt OR Ausschreibung OR Vergabe OR Bewerbung ' + (eventYear || (today.getUTCFullYear() + 1));

  out.push({
    json: {
      title: d.title || src.title || null,
      organizer: d.organizer || null,
      location: d.location || null,
      region: src.region || null,
      eventDate,
      eventYear,
      sourceDate,
      applicationDeadline,
      dateAssumed,
      monthsAhead: months === null ? null : Math.round(months),
      jubileeYears: Number.isFinite(jy) ? jy : null,
      foundingYear,
      festwirtStatus: fs,
      leadType,
      eventType: et,
      incumbentFestwirt: d.incumbentFestwirt || null,
      brauereiPartner: d.brauereiPartner || null,
      planningSignal: ps,
      recurring,
      contactName: d.contactName || null,
      contactRole: d.contactRole || null,
      contactEmail: d.contactEmail || null,
      contactPhone: d.contactPhone || null,
      emergency,
      recheckAt: null,
      eventKey,
      sourceUrl: src.url,
      sourceUrlNormalized: src.sourceUrlNormalized || null,
      nimModel: src.nimModel || null,
      score,
      scoreReason: reasons.join(', ').slice(0, 200),
      runId: src.runId || '',
      todayIso,
      useMockTavily: src.useMockTavily === true,
      verifyQuery,
      originalSnippet: src.snippet || '',
      status: 'new',
      discoveredAt: new Date().toISOString(),
    },
  });
}

const byKey = new Map();
for (const o of out) {
  const ex = byKey.get(o.json.eventKey);
  if (!ex || o.json.score > ex.json.score) byKey.set(o.json.eventKey, o);
}
const finalOut = Array.from(byKey.values())
  .sort((a, b) => (b.json.emergency ? 1 : 0) - (a.json.emergency ? 1 : 0) || b.json.score - a.json.score)
  .slice(0, maxVerify);

if (finalOut.length === 0 && inputs.length > 0) {
  if (lineageErrors === inputs.length) throw new Error('Lineage verloren: ' + lineageErrors + '/' + inputs.length);
  if (authErr > 0) throw new Error('Auth-Fehler (' + authErr + ') - Credential nim pruefen: ' + firstError);
  if (route404 >= inputs.length * 0.8) throw new Error('Route 404 bei ' + route404 + '/' + inputs.length);
  if (model404 >= inputs.length * 0.8) throw new Error('Modell 404 bei ' + model404 + '/' + inputs.length);
  if (truncated + reasoningOnly >= inputs.length * 0.5) throw new Error('Nur Reasoning statt JSON (' + truncated + ' truncated, ' + reasoningOnly + ' reasoning-only).');
  if (httpErrors >= inputs.length * 0.8) throw new Error('LLM-Calls fehlgeschlagen (' + httpErrors + '/' + inputs.length + '): ' + firstError);
}

const stage1Diag = { notEvent, takenSkip, closedSkip, farSkip, expiredDeadlineSkip, pastEventSkip, oldSourceSkip, noDateSkip, knownEventSkip, lowScore };
if (!finalOut.length) {
  return [{ json: { _empty: true, stage1Diag } }];
}
finalOut[0].json.stage1Diag = stage1Diag;
return finalOut;

const q = $json.verifyQuery || '';
function plusDays(days) { const d = new Date(); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().slice(0, 10); }
function de(iso) { const p = iso.split('-'); return p[2] + '.' + p[1] + '.' + p[0]; }
return [{
