function extractJson(text) {
  if (!text || typeof text !== 'string') return null;
  const t = text.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(t); } catch (e) {}
  const s = t.indexOf('{'), e2 = t.lastIndexOf('}');
  if (s !== -1 && e2 > s) { try { return JSON.parse(t.slice(s, e2 + 1)); } catch (e) {} }
  return null;
}
function parseIso(raw) {
  if (!raw) return null;
  let ds = String(raw).trim();
  const de = ds.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (de) ds = de[3] + '-' + de[2].padStart(2, '0') + '-' + de[1].padStart(2, '0');
  if (!/^\d{4}-\d{2}-\d{2}/.test(ds)) return null;
  const dt = new Date(ds.slice(0, 10) + 'T00:00:00Z');
  return isNaN(dt.getTime()) ? null : { iso: ds.slice(0, 10), dt };
}

const today = new Date();
