    let content = (choice.message || {}).content;
    if (Array.isArray(content)) content = content.map(c => (c && c.text) || '').join('');
    e = extractJson(content);
  }

  // Wenn die Nachrecherche zeigt, dass es kein relevanter Verein ist -> raus
  if (e && e.isRelevantClub === false) continue;

  const visitParsed = e ? parseIso(e.nextVisitDate) : null;
  const nextVisitDate = (visitParsed && visitParsed.dt.getTime() >= todayStartUtc) ? visitParsed.iso : null;
  const nextVisitEvent = (e && e.nextVisitEvent && (!visitParsed || visitParsed.dt.getTime() >= todayStartUtc))
    ? String(e.nextVisitEvent).slice(0, 160)
    : null;
  const nextVisitUrl = (e && e.nextVisitUrl && /^https?:\/\//i.test(String(e.nextVisitUrl))) ? String(e.nextVisitUrl) : null;

