  let nextAction = src.nextAction;
  if (nextVisitEvent) {
    nextAction = 'Bei „' + nextVisitEvent + '“' + (nextVisitDate ? (' am ' + nextVisitDate.split('-').reverse().join('.')) : '') + ' persönlich vorbeischauen'
      + (contactName ? (' und ' + (contactRole ? contactRole + ' ' : '') + contactName + ' ansprechen') : ' und Vorstand kennenlernen')
      + ' (Jubiläum ' + src.eventYear + ').';
